function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 200000) return 'nums needs 2 to 200000 values.';
  if (nums.length % 2 !== 0) return 'nums must have an even length.';
  let balance = 0;
  for (const v of nums) {
    if (!Number.isInteger(v) || v === 0 || Math.abs(v) > 100000) return 'Each value is a nonzero integer with |value| <= 100000.';
    balance += v > 0 ? 1 : -1;
  }
  if (balance !== 0) return 'nums needs as many positive values as negative ones.';
  return null;
}

