function generate(rand, size) {
  const half = size === 'large' ? 1000 : 1 + Math.floor(rand() * 5);
  const top = size === 'large' ? 100000 : (rand() < 0.5 ? 3 : 100000);
  const mag = () => 1 + Math.floor(rand() * top);
  const nums = [];
  for (let i = 0; i < half; i++) nums.push(mag(), -mag());
  const style = rand();
  if (style < 0.2) {
    nums.sort((a, b) => b - a);
  } else if (style < 0.3) {
    nums.sort((a, b) => a - b);
  } else {
    for (let i = nums.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [nums[i], nums[j]] = [nums[j], nums[i]];
    }
  }
  return [nums];
}
